    /**
     * Kopiert Teilmaßnahme aus der IT-Fachplanung des vorherigen IT-Gesamtplans in die neue
     * @param DienstStelle $dienstStelle Dienststelle der zu kopierenden IT-Fachplanung
     * @param GesamtPlan $gesamtPlan Gesamtplan
     * @param GesamtPlan $vorherigerGesamtPlan vorheriger Gesamtplan
     * @param int $redakteurLevel Zugriffsrechte-Level des Redakteurs
     * @return string "OK" oder Fehlermeldung
     */
    protected static function copyTeilMassnahmen(
        DienstStelle $dienstStelle,
        GesamtPlan $gesamtPlan,
        GesamtPlan $vorherigerGesamtPlan,
        int $redakteurLevel
    ): string {
        // bereits mit copyMassnahmen kopierte Maßnahmen ermitteln
        $sql = "SELECT id, fk_kopie_von FROM massnahme WHERE fk_dienststelle='{$dienstStelle->nummer}' AND fk_gesamtplan={$gesamtPlan->jahr}";
        $data = Page::db()->queryToArray($sql);

        /* Basis Datenfelder teilmassnahme */
        // deleted, valid, etc. werden nicht übernommen, sondern auf default gesetzt.
        $insertFields = 'Ident,lft_nummer,status_markiert,redakteur_level,fk_massnahme,fk_kopie_von,full_text,';
        /* Weiter dynamische Felder */
        $moreFields = implode(', ', self::getFormFieldSqlNames($gesamtPlan->jahr, 'teilmassnahme'));
        $insertFields .= $moreFields;

        foreach ($data as $massnahmeData) {
            $mId = (int)$massnahmeData['id'];
            $fromId = (int)$massnahmeData['fk_kopie_von'];

            /* Basis Datenfelder teilmassnahme */
            $selectFields = "Ident,lft_nummer,'kopiert',$redakteurLevel,$mId,id,full_text,";
            $selectFields .= $moreFields;
            $sql = "INSERT INTO teilmassnahme ($insertFields)\n"
                . "SELECT $selectFields\n"
                . "FROM teilmassnahme WHERE deleted = 0 AND aenderungs_antrag = 0\n"
                . "AND fk_massnahme = $fromId";

            $statement = Page::db()->prepare($sql);
            if ($statement->execute()) {
                $resultMessage = self::calcFinanzPlanungenAfterCopy($mId, $vorherigerGesamtPlan);
                if ($resultMessage !== "OK") {
                    // Schleifenabbruch!!
                    return $resultMessage;
                }
            } else {
                //$errInfo = $statement->errorInfo();
                //return "DB-Fehler: " . $errInfo[0] . " | " . $errInfo[1] . "\nFehlermeldung: " . $errInfo[2] . "\nSQL-Anweisung: " . $statement->queryString . "\n\n";
                return "Es ist ein Datenbankfehler aufgetreten (3).";
            }
        }
        return "OK";
    }

    protected static function calcFinanzPlanungenAfterCopy(
        int $massnahmeId,
        GesamtPlan $vorherigerGesamtPlan
    ): string {
        // 1. Verschiebe die Spalteninhalte der Jahre
        if ($vorherigerGesamtPlan->jahr2 === null) {
            // Vorheriger Gesamtplan war einjährig, verschiebe Beträge um ein Jahr
            $sql = 'UPDATE teilmassnahme SET '
                . 'Jahr_Minus2=Jahr_Minus1,Jahr_Minus1=Jahr1,Jahr1=Jahr2,Jahr2=Jahr3,Jahr3=Jahr4,Jahr4=Jahr5,'
                . 'Jahr5=NULL,Verpflichtungsermaechtigungen=Verpflichtungsermaechtigungen_Jahr2,'
                . 'Verpflichtungsermaechtigungen_Jahr2=NULL'
                . " WHERE fk_massnahme = $massnahmeId";
        } else {
            // Vorheriger Gesamtplan war zweijährig, verschiebe Beträge um zwei Jahre
            $sql = 'UPDATE teilmassnahme SET '
                . 'Jahr_Minus2=Jahr1,Jahr_Minus1=Jahr2,Jahr1=Jahr3,Jahr2=Jahr4,Jahr3=Jahr5,Jahr4=NULL,Jahr5=NULL,'
                . 'Verpflichtungsermaechtigungen=NULL,Verpflichtungsermaechtigungen_Jahr2=NULL'
                . " WHERE fk_massnahme = $massnahmeId";
        }

        $statement = Page::db()->prepare($sql);
        if ($statement->execute()) {
            return Massnahme::calcFinanzPlanungen($massnahmeId);
        } else {
            $errInfo = $statement->errorInfo();
            return "DB-Fehler: " . $errInfo[0] . " | " . $errInfo[1] . "\nFehlermeldung: " . $errInfo[2] . "\nSQL-Anweisung: " . $statement->queryString . "\n\n";
            //return "Es ist ein Datenbankfehler aufgetreten (4).";
        }

        return $sql;
    }

